<?php $page_title='Customer Details';require 'includes/header.php';$id=(int)($_GET['id']??0);$s=$pdo->prepare("SELECT u.*,COUNT(o.id) orders_count,COALESCE(SUM(CASE WHEN o.order_status<>'cancelled' THEN o.total ELSE 0 END),0) spending,(SELECT COUNT(*) FROM wishlist w WHERE w.user_id=u.id) wishlist_count FROM users u LEFT JOIN orders o ON o.user_id=u.id WHERE u.id=? AND u.role='customer' GROUP BY u.id");$s->execute([$id]);$c=$s->fetch();if(!$c)exit('Customer not found.');$s=$pdo->prepare("SELECT * FROM orders WHERE user_id=? ORDER BY created_at DESC");$s->execute([$id]);$orders=$s->fetchAll();?>
<div class="page-head"><div><h1><?=e($c['name'])?></h1><p>Customer profile & complete order history.</p></div><a class="btn light" href="customers.php">← Customers</a></div><div class="cards"><div class="stat"><div class="label">Email</div><div class="num" style="font-size:16px"><?=e($c['email'])?></div></div><div class="stat"><div class="label">Phone</div><div class="num" style="font-size:16px"><?=e($c['phone']??'—')?></div></div><div class="stat"><div class="label">Total Orders</div><div class="num"><?=$c['orders_count']?></div></div><div class="stat"><div class="label">Total Spending</div><div class="num"><?=money((float)$c['spending'])?></div></div><div class="stat"><div class="label">Wishlist Items</div><div class="num"><?=$c['wishlist_count']?></div></div><div class="stat"><div class="label">Registration</div><div class="num" style="font-size:16px"><?=date('M d, Y',strtotime($c['created_at']))?></div></div></div><div class="panel"><h2>Order history</h2><div class="table-wrap"><table><tr><th>Order</th><th>Date</th><th>Total</th><th>Payment</th><th>Status</th><th></th></tr><?php foreach($orders as $o):?><tr><td>#<?=$o['id']?></td><td><?=date('M d, Y',strtotime($o['created_at']))?></td><td><?=money((float)$o['total'])?></td><td><?=e(strtoupper($o['payment_method']))?></td><td><span class="badge <?=e($o['order_status'])?>"><?=e(ucfirst($o['order_status']))?></span></td><td><a href="order-details.php?id=<?=$o['id']?>">View order</a></td></tr><?php endforeach;?></table></div></div><?php require 'includes/footer.php';?>
